            int n = 11;
            intN x = new intN(n, Allocator.Temp);
            intN y = new intN(n, Allocator.Temp);
            for (int i = 0; i < n; i++)
            {
                x[i] = (int)(i - 5);
                y[i] = (int)(5 - i);
            }
            intN y0 = y.Copy();

            x.maxInPlace(y); // x = max(x, y) ; y untouched

            for (int i = 0; i < n; i++)
            {
                int a = (int)(i - 5), b = (int)(5 - i);
                Assert.IsTrue(x[i] == (a > b ? a : b));
